<script setup lang="ts">import{computed,shallowRef}from"vue";import{useRoute}from"vue-router";import AppSidebar from"../components/layout/AppSidebar.vue";import AppTopbar from"../components/layout/AppTopbar.vue";import ContextRail from"../components/layout/ContextRail.vue";import GlobalSearchDialog from"../components/layout/GlobalSearchDialog.vue";import MobileNavigation from"../components/layout/MobileNavigation.vue";const collapsed=shallowRef(false);const searchOpen=shallowRef(false);const mobileOpen=shallowRef(false);const railOpen=shallowRef(false);const route=useRoute();const hasContextRail=computed(()=>Boolean(route.meta.feature?.requiresContextRail));</script><template><div class="shell" :class="{ 'with-context-rail': hasContextRail }"><AppSidebar :collapsed="collapsed" @toggle="collapsed=!collapsed"/><div class="work"><AppTopbar @open-search="searchOpen=true" @open-menu="mobileOpen=true"/><main class="content"><RouterView/></main></div><ContextRail :open="railOpen" @close="railOpen=false"/><MobileNavigation :open="mobileOpen" @close="mobileOpen=false"/><GlobalSearchDialog v-model="searchOpen"/></div></template><style scoped>.shell{display:grid;grid-template-columns:auto minmax(0,1fr);min-height:100vh}.shell.with-context-rail{grid-template-columns:auto minmax(0,1fr) var(--rail)}.work{min-width:0}.content{min-height:calc(100vh - 65px)}@media(max-width:1100px){.shell.with-context-rail{grid-template-columns:auto minmax(0,1fr)}}@media(max-width:900px){.shell{display:block}.shell>:first-child{display:none}}</style>
